type Finding struct {
	// ArchivedAt Set while the finding itself (or with its scan) is archived; a finding of an archived project is archived through the project.
	ArchivedAt *time.Time          `json:"archived_at,omitempty"`
	ArchivedBy *openapi_types.UUID `json:"archived_by,omitempty"`

	// AssetExposure The exposure of the finding's asset (null = unknown or no asset).
	AssetExposure *FindingAssetExposure `json:"asset_exposure,omitempty"`
	AssetId       *openapi_types.UUID   `json:"asset_id,omitempty"`
	AssigneeEmail *string               `json:"assignee_email,omitempty"`

	// AssigneeId Who owns fixing it.
	AssigneeId *openapi_types.UUID `json:"assignee_id,omitempty"`

	// Category `cloud` is CSPM, `kubernetes` is KSPM.
	Category *Category `json:"category,omitempty"`

	// CorrelationKey Groups the same CVE+package, or the same non-CVE finding location+CWE, across scanners.
	CorrelationKey *string    `json:"correlation_key,omitempty"`
	CreatedAt      *time.Time `json:"created_at,omitempty"`

	// Custom Custom-field values by key — text, a number, a `YYYY-MM-DD` date, an enum option or a user id. Unset fields are absent.
	Custom *CustomValues `json:"custom,omitempty"`
	Cve    *[]string     `json:"cve,omitempty"`

	// Cvss CVSS base score — the scanner's when it reported one, else NVD's (`cvss_source = nvd`).
	Cvss *float32 `json:"cvss,omitempty"`

	// CvssSource `nvd` when `cvss` was filled from NVD because the scanner gave none.
	CvssSource *FindingCvssSource `json:"cvss_source,omitempty"`

	// CvssVector NVD's CVSS vector for the CVE (v3.1, else v3.0, else v4.0); NVD_ENABLED.
	CvssVector *string `json:"cvss_vector,omitempty"`

	// CvssVersion Example: 3.1
	CvssVersion *string `json:"cvss_version,omitempty"`
	Cwe         *int    `json:"cwe,omitempty"`

	// DepDepth Hops from the root component.
	DepDepth *int `json:"dep_depth,omitempty"`

	// DepDirect Did the project ask for this dependency, or did it come along? Null = no SBOM data.
	DepDirect *bool `json:"dep_direct,omitempty"`

	// DepScope Where the dependency is used, read from the SBOM itself. `dev` never ships.
	// Empty means the SBOM didn't say — which is **never** treated as safe.
	DepScope    *DepScope `json:"dep_scope,omitempty"`
	Description *string   `json:"description,omitempty"`

	// DuplicateCount How many tools reported this issue.
	DuplicateCount *int `json:"duplicate_count,omitempty"`

	// DuplicateOf Set when another tool's report of this same issue was elected primary. Hidden from lists by default.
	DuplicateOf *openapi_types.UUID `json:"duplicate_of,omitempty"`

	// Epss Probability of exploitation in the next 30 days (FIRST.org).
	Epss               *float32   `json:"epss,omitempty"`
	ExceptionBy        *string    `json:"exception_by,omitempty"`
	ExceptionExpiresAt *time.Time `json:"exception_expires_at,omitempty"`
	ExceptionReason    *string    `json:"exception_reason,omitempty"`

	// ExploitMaturity The strongest public exploit known for the finding's CVEs: `weaponized`
	// (a Metasploit exploit module) or `poc` (ExploitDB, a Metasploit scanner,
	// a Nuclei template). Empty = none known, which is not evidence of safety.
	ExploitMaturity *FindingExploitMaturity `json:"exploit_maturity,omitempty"`
	FilePath        *string                 `json:"file_path,omitempty"`

	// Fingerprint Stable identity within a project.
	Fingerprint *string `json:"fingerprint,omitempty"`

	// FirstScanId The scan that first reported it; equal to last_scan_id while it has been seen once ("new").
	FirstScanId *openapi_types.UUID `json:"first_scan_id,omitempty"`
	FirstSeenAt *time.Time          `json:"first_seen_at,omitempty"`

	// FixedVersion The version to upgrade to.
	FixedVersion *string             `json:"fixed_version,omitempty"`
	Id           *openapi_types.UUID `json:"id,omitempty"`

	// Kev On a Known Exploited Vulnerabilities catalog — it is being exploited right now (any of `kev_sources`).
	Kev *bool `json:"kev,omitempty"`

	// KevRansomware A KEV catalog asserting the finding says the flaw is known to be used in
	// ransomware campaigns (`knownRansomwareCampaignUse` in CISA KEV and VulnCheck KEV).
	KevRansomware *bool `json:"kev_ransomware,omitempty"`

	// KevSources The KEV catalogs asserting it (sorted): `cisa` (CISA KEV), `enisa` (ENISA EU
	// Vulnerability Database, exploited), `vulncheck` (VulnCheck KEV). Matched through
	// aliases — the finding's CVEs, rule id and the advisory's aliases.
	KevSources *[]FindingKevSources `json:"kev_sources,omitempty"`

	// LastScanId The latest scan that reported it.
	LastScanId           *openapi_types.UUID     `json:"last_scan_id,omitempty"`
	LastSeenAt           *time.Time              `json:"last_seen_at,omitempty"`
	Line                 *int                    `json:"line,omitempty"`
	Metadata             *map[string]interface{} `json:"metadata,omitempty"`
	PackageName          *string                 `json:"package_name,omitempty"`
	PackageVersion       *string                 `json:"package_version,omitempty"`
	PlannedRemediationAt *openapi_types.Date     `json:"planned_remediation_at,omitempty"`

	// Priority severity × exploitability × reachability × asset exposure. A KEV
	// listing triples the weight; EPSS or a public exploit raise it up to
	// 2.5× (Metasploit module) / 1.5× (proof of concept); a dev-only
	// dependency quarters it; an internet-facing asset raises it 1.25×, an
	// isolated one discounts it to 0.75× (unknown never discounts).
	// Sort by this to work the backlog exploit-first.
	Priority   *float32            `json:"priority,omitempty"`
	ProjectId  *openapi_types.UUID `json:"project_id,omitempty"`
	Purl       *string             `json:"purl,omitempty"`
	ResolvedAt *time.Time          `json:"resolved_at,omitempty"`

	// RiskAcceptance The live risk acceptance covering the finding (id
	RiskAcceptance *map[string]interface{} `json:"risk_acceptance,omitempty"`

	// RuleId The tool's check id. Feeds compliance mapping.
	RuleId   *string   `json:"rule_id,omitempty"`
	Scanner  *string   `json:"scanner,omitempty"`
	Severity *Severity `json:"severity,omitempty"`

	// SeverityManual A person set the severity; re-scans and triage rules keep it until reset.
	SeverityManual *bool `json:"severity_manual,omitempty"`

	// SlaDays The remediation window this finding's severity gets under its project's SLA policy. Null = no SLA.
	SlaDays *int `json:"sla_days,omitempty"`

	// SlaDueAt First seen + the window + any time spent in an exception state (the clock pauses while risk-accepted / false positive / won't fix).
	SlaDueAt *time.Time `json:"sla_due_at,omitempty"`

	// SlaStatus Where a finding stands against its deadline. `due_soon` = live and in the
	// last 25% of its window; `paused` = in an exception state (risk accepted,
	// false positive, won't fix), which stops the clock; `met` / `missed` =
	// remediated before / after the deadline; `none` = no SLA for its severity.
	SlaStatus *SLAStatus `json:"sla_status,omitempty"`

	// SourceUrl GET /findings/{id} only: file:line in the repository at the scanned commit (GitHub, GitLab, Bitbucket, Azure DevOps, Gitea/Forgejo); absent when the project's repo_url isn't recognized.
	SourceUrl *string `json:"source_url,omitempty"`

	// Status `remediated` is set by the system when a scanner stops reporting a finding —
	// don't set it by hand. The triage states are sticky: they survive re-scans.
	Status *FindingStatus `json:"status,omitempty"`

	// Tags User-managed labels, sorted (lowercase letters, digits, `. _ : / -`; up to 20). Scanners never set them; re-ingest keeps them.
	Tags  *[]string `json:"tags,omitempty"`
	Title *string   `json:"title,omitempty"`

	// TitleManual A person overrode the scanner's title (it survives re-scans until reset).
	TitleManual *bool      `json:"title_manual,omitempty"`
	UpdatedAt   *time.Time `json:"updated_at,omitempty"`
	Url         *string    `json:"url,omitempty"`

	// VersionId The branch / release this finding lives on.
	VersionId *openapi_types.UUID `json:"version_id,omitempty"`
}

// FindingAssetExposure The exposure of the finding's asset (null = unknown or no asset).
type FindingAssetExposure string

