// GatePolicy Every threshold is optional; unset means "don't check it". `-1` also means
// unlimited, so a policy can be relaxed without deleting it.
type GatePolicy struct {
	// BaselineBranch With new_only, compare against this branch/version instead of the single-scan heuristic — a finding is new only if it isn't already open there (by the same cross-scan identity Upsert/CloseMissing use). Overridable per request with ?baseline=.
	BaselineBranch *string `json:"baseline_branch,omitempty"`

	// BlockKev Fail on any open KEV finding.
	BlockKev *bool `json:"block_kev,omitempty"`

	// BlockLicense Fail on any open license finding (e.g. a violation of a license-only component policy).
	BlockLicense *bool `json:"block_license,omitempty"`

	// BlockSlaBreach Fail while any open finding is past its remediation SLA.
	BlockSlaBreach *bool `json:"block_sla_breach,omitempty"`
	Enabled        *bool `json:"enabled,omitempty"`

	// KevSources Limit `block_kev` to findings these catalogs assert; empty = any catalog.
	KevSources *[]GatePolicyKevSources `json:"kev_sources,omitempty"`

	// MaxCritical Fail if open criticals exceed this.
	MaxCritical *int `json:"max_critical,omitempty"`

	// MaxEpss Fail if any open finding's EPSS reaches this (0–1).
	MaxEpss *float32 `json:"max_epss,omitempty"`
	MaxHigh *int     `json:"max_high,omitempty"`

	// MaxInfo Fail if open info findings exceed this.
	MaxInfo *int `json:"max_info,omitempty"`

	// MaxLow Fail if open lows exceed this.
	MaxLow *int `json:"max_low,omitempty"`

	// MaxMedium Fail if open mediums exceed this.
	MaxMedium *int `json:"max_medium,omitempty"`

	// MaxRiskScore Fail if the gated version's business-weighted risk score (the same figure the project summary shows) exceeds this.
	MaxRiskScore *float32 `json:"max_risk_score,omitempty"`

	// NewOnly Ignore pre-existing debt; gate only on what this scan introduced.
	NewOnly *bool `json:"new_only,omitempty"`
}

// GatePolicyKevSources defines model for GatePolicy.KevSources.
type GatePolicyKevSources string

// GateResult Example: {"new_only":false,"passed":true,"scope":"none","stats":{"max_epss":0,"open_critical":2,"open_high":3,"open_kev":0,"open_kev_sources":{},"open_license":0,"sla_breached":0},"version_id":"","violations":[]}
type GateResult struct {
	// Baseline The branch/version name new_only was compared against, when one was used; empty = the single-scan heuristic.
	Baseline *string `json:"baseline,omitempty"`
	NewOnly  *bool   `json:"new_only,omitempty"`
	Passed   *bool   `json:"passed,omitempty"`

	// Scope Which policy was used.
	Scope *GateResultScope `json:"scope,omitempty"`
	Stats *struct {
		MaxEpss      *float32 `json:"max_epss,omitempty"`
		OpenCritical *int     `json:"open_critical,omitempty"`
		OpenHigh     *int     `json:"open_high,omitempty"`
		OpenInfo     *int     `json:"open_info,omitempty"`
		OpenKev      *int     `json:"open_kev,omitempty"`

		// OpenKevSources Open KEV findings by the exact catalog set asserting them, e.g. `cisa,enisa` → 2.
		OpenKevSources *map[string]int `json:"open_kev_sources,omitempty"`
		OpenLicense    *int            `json:"open_license,omitempty"`
		OpenLow        *int            `json:"open_low,omitempty"`
		OpenMedium     *int            `json:"open_medium,omitempty"`

		// RiskScore Same definition as the project summary's risk_score
		RiskScore   *float32 `json:"risk_score,omitempty"`
		SlaBreached *int     `json:"sla_breached,omitempty"`
	} `json:"stats,omitempty"`

	// VersionId The project version evaluated; empty = the default version.
	VersionId  *string `json:"version_id,omitempty"`
	Violations *[]struct {
		// Message Example: 1 open critical findings exceed the limit of 0
		Message *string `json:"message,omitempty"`

		// Rule Example: max_critical
		Rule *string `json:"rule,omitempty"`
	} `json:"violations,omitempty"`
}

// GateResultScope Which policy was used.
type GateResultScope string

