// TriageRule Conditions → action. Unset conditions are ignored; all set conditions must hold.
type TriageRule struct {
	Action *TriageRuleAction `json:"action,omitempty"`

	// ApprovalStatus Only `approved` rules apply. With `TRIAGE_RULES_REQUIRE_APPROVAL=true`, creating
	// **or editing** a rule makes it `pending` — so editing an approved rule stops it
	// applying until a different admin re-approves it. Otherwise rules are approved on save.
	ApprovalStatus *TriageRuleApprovalStatus `json:"approval_status,omitempty"`
	ApprovedAt     *time.Time                `json:"approved_at,omitempty"`
	ApprovedBy     *openapi_types.UUID       `json:"approved_by,omitempty"`

	// Category `cloud` is CSPM, `kubernetes` is KSPM.
	Category *Category `json:"category,omitempty"`

	// Continue Chain this rule: after it acts, the rules after it still evaluate, against the
	// finding as it left it (raise a severity, then act on the raised severity).
	// Without it the first matching rule is the only one that acts.
	Continue  *bool               `json:"continue,omitempty"`
	CreatedAt *time.Time          `json:"created_at,omitempty"`
	CreatedBy *openapi_types.UUID `json:"created_by,omitempty"`

	// CustomField For `set_custom_field`: the finding custom field's key.
	CustomField *string `json:"custom_field,omitempty"`

	// CustomValue For `set_custom_field`: the value, checked against the field's type when the rule is
	// saved (`null` clears the field). A finding already holding it is left alone; a value
	// not valid for a finding (a field scoped to another organization, a user who can't
	// see the project) skips that finding.
	CustomValue interface{} `json:"custom_value,omitempty"`
	CveIn       *[]string   `json:"cve_in,omitempty"`
	Cwe         *int        `json:"cwe,omitempty"`

	// DepScope Where the dependency is used, read from the SBOM itself. `dev` never ships.
	// Empty means the SBOM didn't say — which is **never** treated as safe.
	DepScope *DepScope `json:"dep_scope,omitempty"`

	// DepTransitive Match only dependencies the project never asked for. A finding with no SBOM data never matches.
	DepTransitive *bool `json:"dep_transitive,omitempty"`
	Enabled       *bool `json:"enabled,omitempty"`

	// Expression Optional [CEL](https://cel.dev) condition that must also hold, over `finding`
	// (`scanner`, `category`, `rule_id`, `title`, `severity`, `status`, `cve`,
	// `cwe`, `cvss`, `epss`, `kev`, `kev_sources` (catalogs: `cisa`, `enisa`, `vulncheck`),
	// `package`, `version`, `fixed_version`, `purl`, `file_path`, `url`, `tags`, `dep_direct`, `dep_depth`, `dep_scope`,
	// `custom.<key>`) and `project` (`criticality`, `custom.<key>`), e.g.
	// `finding.cvss >= 9 && "internet-facing" in finding.tags`. A custom field must be
	// defined to be named; an unset one never matches (`has(finding.custom.team)` tests it).
	// Unknown facts are null and never match; syntax errors, misspelled fields and
	// non-boolean results are rejected with a 400.
	Expression *string `json:"expression,omitempty"`

	// HitCount Findings this rule actually changed, summed over every ingest and backlog apply.
	HitCount *int                `json:"hit_count,omitempty"`
	Id       *openapi_types.UUID `json:"id,omitempty"`

	// Kev When true, match only findings a KEV catalog (CISA, ENISA, VulnCheck) lists.
	Kev       *bool      `json:"kev,omitempty"`
	LastHitAt *time.Time `json:"last_hit_at,omitempty"`

	// MinEpss Match findings whose EPSS is at least this (inclusive). A finding with no EPSS score never matches.
	MinEpss      *float32  `json:"min_epss,omitempty"`
	Name         *string   `json:"name,omitempty"`
	NewSeverity  *Severity `json:"new_severity,omitempty"`
	PackageRegex *string   `json:"package_regex,omitempty"`

	// PathRegex Example: ^test/
	PathRegex *string `json:"path_regex,omitempty"`

	// ProjectCriticality Match findings whose project has one of these business criticalities. Empty = any.
	ProjectCriticality *[]TriageRuleProjectCriticality `json:"project_criticality,omitempty"`

	// ProjectId Null = applies to every project.
	ProjectId *openapi_types.UUID `json:"project_id,omitempty"`

	// Reason Recorded in the finding's audit trail.
	Reason     *string             `json:"reason,omitempty"`
	RejectedAt *time.Time          `json:"rejected_at,omitempty"`
	RejectedBy *openapi_types.UUID `json:"rejected_by,omitempty"`
	RuleId     *string             `json:"rule_id,omitempty"`
	Scanner    *string             `json:"scanner,omitempty"`
	Severities *[]Severity         `json:"severities,omitempty"`

	// SortOrder Evaluation order (lowest first). The first match acts.
	SortOrder *int       `json:"sort_order,omitempty"`
	UpdatedAt *time.Time `json:"updated_at,omitempty"`

	// UpdatedBy Last editor.
	UpdatedBy *openapi_types.UUID `json:"updated_by,omitempty"`
}

