// ListFindingsParams defines parameters for ListFindings.
type ListFindingsParams struct {
	ProjectId *openapi_types.UUID `form:"project_id,omitempty" json:"project_id,omitempty"`
	AssetId   *openapi_types.UUID `form:"asset_id,omitempty" json:"asset_id,omitempty"`
	Status    *FindingStatus      `form:"status,omitempty" json:"status,omitempty"`
	Severity  *Severity           `form:"severity,omitempty" json:"severity,omitempty"`
	Category  *Category           `form:"category,omitempty" json:"category,omitempty"`
	Scanner   *string             `form:"scanner,omitempty" json:"scanner,omitempty"`

	// RuleId Only findings of this rule — e.g. a component policy's violations (`scanner=policy&rule_id=<policy id>`).
	RuleId *string `form:"rule_id,omitempty" json:"rule_id,omitempty"`

	// Kev Only findings a KEV catalog (CISA, ENISA EUVD, VulnCheck) lists as known-exploited.
	Kev *bool `form:"kev,omitempty" json:"kev,omitempty"`

	// KevRansomware Only findings a KEV catalog marks as known to be used in ransomware campaigns.
	KevRansomware *bool `form:"kev_ransomware,omitempty" json:"kev_ransomware,omitempty"`

	// Active Only findings still awaiting a fix (open or confirmed).
	Active *bool `form:"active,omitempty" json:"active,omitempty"`

	// Reachable Only findings whose dependency ships (not dev-only) **and** was depended
	// on directly. Findings with no SBOM data are kept — unknown is never
	// treated as safe.
	Reachable *bool `form:"reachable,omitempty" json:"reachable,omitempty"`

	// Direct Only direct dependencies.
	Direct *bool     `form:"direct,omitempty" json:"direct,omitempty"`
	Scope  *DepScope `form:"scope,omitempty" json:"scope,omitempty"`

	// ScanId Only findings this scan reported.
	ScanId *openapi_types.UUID `form:"scan_id,omitempty" json:"scan_id,omitempty"`

	// New Only findings first seen in the scan that reported them — "what this change introduced".
	New *bool `form:"new,omitempty" json:"new,omitempty"`

	// IncludeDuplicates Include each tool's duplicate report instead of one deduplicated issue.
	IncludeDuplicates *bool `form:"include_duplicates,omitempty" json:"include_duplicates,omitempty"`

	// Archived List archived records instead of live ones (requires `owner`; a portfolio-wide list narrows to the projects you own).
	Archived *ArchivedFilter `form:"archived,omitempty" json:"archived,omitempty"`

	// Sla Only findings in this SLA state.
	Sla *SLAFilter `form:"sla,omitempty" json:"sla,omitempty"`

	// Q Full-text search (websearch syntax: words in any order, `"a phrase"`,
	// `-excluded`, `or`) over title, rule id, CVEs, package, purl, tags, file
	// path and description. Matching is on whole tokens, case-insensitive, no
	// stemming — `CVE-2021-44228`, `log4j-core`, `lodash`. Without `sort`,
	// results come most relevant first.
	Q *SearchFilter `form:"q,omitempty" json:"q,omitempty"`

	// Tag Comma-separated tags; only findings carrying **all** of them.
	Tag *TagFilter `form:"tag,omitempty" json:"tag,omitempty"`

	// CfKey Custom-field filter; repeatable, one per field (at most 10). `?cf.<key>=value`
	// matches the stored value (text, enum, date, user id, or a number);
	// `?cf.<key>.gte=` / `.gt=` / `.lte=` / `.lt=` compare numbers numerically and
	// dates (`YYYY-MM-DD`) in order; `?cf.<key>.set=true|false` tests whether the
	// field is set. The literal parameter names are e.g. `cf.team`, `cf.score.gte`.
	CfKey *CustomFieldFilter `form:"cf.{key},omitempty" json:"cf.{key},omitempty"`

	// Assignee `me`, `none` (unassigned), or a user id.
	Assignee *AssigneeFilter `form:"assignee,omitempty" json:"assignee,omitempty"`

	// VersionId Only findings on this project version (branch / release).
	VersionId *VersionFilter `form:"version_id,omitempty" json:"version_id,omitempty"`

	// EngagementId Only findings an engagement's scans or manual reports found (first or last seen in one of them), on any version.
	EngagementId *EngagementFilter `form:"engagement_id,omitempty" json:"engagement_id,omitempty"`

	// Exploit Only findings with a public exploit — `weaponized`, `poc`, or `any` (either).
	Exploit *ListFindingsParamsExploit `form:"exploit,omitempty" json:"exploit,omitempty"`

	// AllVersions Include every branch and release. By default only each project's default version is listed (or the scan's, with `scan_id`).
	AllVersions *bool                   `form:"all_versions,omitempty" json:"all_versions,omitempty"`
	Sort        *ListFindingsParamsSort `form:"sort,omitempty" json:"sort,omitempty"`

	// Limit Page size (max 200).
	Limit  *Limit  `form:"limit,omitempty" json:"limit,omitempty"`
	Offset *Offset `form:"offset,omitempty" json:"offset,omitempty"`
}

// ListFindingsParamsExploit defines parameters for ListFindings.
type ListFindingsParamsExploit string

// ListFindingsParamsSort defines parameters for ListFindings.
type ListFindingsParamsSort string

